with d as (select value r from jsonb_array_elements($q$[{"notes":["Make ahead: cook the barbacoa the day before, then shred and reheat gently in the braising liquid. Keeps in the fridge for up to 3 days.","Serve on warm flour tortillas with diced onion, fresh coriander and lime wedges.","This is a weekend cook: take your time and let the low heat do the work.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Heat the oven to 120°C. Toast the dried guajillo and chipotle chillies in a dry pan for 2 minutes until fragrant, then transfer to a bowl and cover with hot water. Let sit for 15 minutes until soft."},{"text":"Drain the rehydrated chillies, then blitz them in a blender with garlic, cumin, oregano, cloves, beef stock, vinegar and salt until smooth. Strain through a sieve if you want a silky paste; for rustic texture, leave it coarse."},{"text":"Pat the brisket dry. Rub all over with the chilli paste until well coated. Wrap tightly in agave or banana leaves and then in foil, sealing the edges."},{"text":"Place the wrapped brisket in a heavy-based pot or Dutch oven. Cover and braise in the oven for 7 to 8 hours, until the meat shreds easily with a fork."},{"text":"Remove from the oven and let rest for 15 minutes. Unwrap carefully, watch out for steam, and shred the beef using two forks, pulling it apart along the grain."},{"text":"Strain the braising liquid into a jug. Skim any fat from the surface and season with salt to taste. Toss the shredded beef with a few tbsp of the braising liquid to keep it moist."}],"id":"9e11ad50-966b-46ee-8321-230475ae1158"},{"notes":["Make it ahead and reheat gently with a splash of milk, it keeps for 3 days in the fridge.","If you can't find broken rice, crush short-grain white rice coarsely with your hands or a rolling pin before cooking."],"id":"b34cfbc0-1a3a-40ae-a5c3-d4644fe171d8"},{"notes":["Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"63b705ec-da62-40f7-814d-589f65673dc4"},{"notes":["Serve with white rice, collard greens or a simple slaw to cool the heat.","The frying pan must be smoking hot, don't skip this step or you won't get that proper blackened crust.","Swap catfish for any firm white fish fillet.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Mix paprika, cayenne, cumin, onion powder, garlic powder, thyme, oregano, black pepper and salt in a shallow dish."},{"text":"Pat the catfish fillets dry with paper towels. Coat both sides generously with the spice mixture, pressing it on so it sticks."},{"text":"Heat the oil in a cast-iron frying pan over high heat until it's smoking and a drop of water beads and rolls across the surface, about 2 minutes."},{"text":"Add the butter and swirl it through the hot oil. When it's foaming and just starting to brown, lay the catfish fillets in the frying pan, they should sizzle hard."},{"text":"Sear without moving them for 3 to 4 minutes, until the crust is dark brown and charred. Flip carefully."},{"text":"Sear the other side for another 2 to 3 minutes, until the fish is cooked through and flakes easily with a fork. Serve hot."}],"id":"69c02bf5-fc98-438e-b85d-e706661bea2c"},{"notes":["Kopytka can be made ahead: shape and boil them, then store in the fridge for up to 2 days. Toss with the mushrooms and onions to warm through.","The dough should stay slightly loose, too much flour and the kopytka become heavy. If it's very sticky, dust with a little more flour, but resist the urge to knead.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Boil the potato in salted water until tender, about 12 minutes. Drain well and pass through a ricer while still hot into a large bowl."},{"text":"Add the flour, egg, and salt to the potato. Mix gently with your hands until just combined, it should feel a little soft and slightly sticky, not smooth. Don't overwork it."},{"text":"Bring a large pot of salted water to a boil. Dust the work surface lightly with flour. Break off a piece of dough about the size of a walnut, roll it roughly into a stick about 5 cm long, and press gently with your thumb to make a small indent (this is the little hoof). Drop each kopytka into the boiling water as you shape them. They will sink, then float to the surface; cook for 2–3 minutes after they float. Drain and spread on a tray to cool."},{"text":"While the kopytka cook, heat the oil in a large pan over medium-high heat. Add the mushrooms and fry, stirring often, until they are golden and any liquid has evaporated, about 8 minutes. Transfer to a plate."},{"text":"Lower the heat to medium and add the onions to the same pan. Cook, stirring now and then, until they are soft and deeply golden, about 12 minutes. Add the garlic and thyme, if using, and cook for another minute."},{"text":"Return the mushrooms to the pan with the onions. Add the drained kopytka and toss gently until everything is warm and coated. Season with salt and black pepper. Serve hot."}],"id":"eb4a1e90-4a18-4dbf-bf7d-8edb3843ddda"},{"notes":["Fresh masa is best, but masa harina (corn flour) works well too: use about 125 g mixed with a little warm water to a smooth paste.","Oaxacan chocolate is grainy and textured, sold as tablets, seek it in Latin or Mexican markets, or use good dark chocolate with a tiny pinch of ground almond added.","A molinillo whisk creates the traditional frothy top, but a regular whisk does the job."],"id":"99a6c6fb-a4f3-40e7-8372-0b057cbfd4e9"},{"steps":[{"text":"If using dried noodles, cook in boiling salted water until just tender, drain well and spread on a tray to cool. Fresh noodles can be used as they are."},{"text":"Heat the oil in a large wok or wide frying pan over high heat. When shimmering, add the sliced garlic and ginger. Stir-fry for about 1 minute until fragrant but not brown."},{"text":"Add the water spinach and toss constantly for 2–3 minutes until it begins to wilt but the stems still have a gentle firmness."},{"text":"Add the cooled noodles to the wok, breaking them apart gently with chopsticks or tongs as you toss. Stir-fry for 2–3 minutes until heated through."},{"text":"Pour the soy sauce and rice vinegar over the noodles and toss well for another minute, letting the flavours coat everything evenly."},{"text":"Taste and season with salt and black pepper. If you like heat, sprinkle with dried chilli flakes."},{"text":"Serve at once, while the noodles are still warm and the spinach stems hold their slight crispness."}],"id":"bbdb520c-b7f5-4aa1-a086-4e2b600a14e9"},{"notes":["Make it a day ahead if you like, the flavours deepen overnight. Reheat gently on the stove.","The scotch bonnet stays whole while cooking so you control the heat. Leave it out if you prefer a gentler dish."],"id":"aa6071dd-3828-4d92-903c-62891d97aab4"},{"notes":["If you don't have a pudding basin, a 1.5-litre heatproof bowl wrapped in foil will work, though you may need to adjust the steaming time slightly.","Leftovers can be reheated gently in the steamer for 30 minutes, or covered in foil in a 150°C oven for about 45 minutes.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat the oil in a large pan over medium-high heat. Season the beef with salt and pepper. Brown the meat in batches, about 3 minutes per batch, until well coloured on all sides. Set aside."},{"text":"In the same pan, cook the onion until soft, about 5 minutes. Add the garlic and tomato paste, stir well, and cook for 2 minutes more."},{"text":"Return the beef to the pan. Pour in the ale and stock, scraping the bottom of the pan. Add the bay leaves and thyme. Bring to a simmer, then remove from heat and leave to cool completely, at least 1 hour. The filling needs to be cold before you add it to the pastry."},{"text":"While the filling cools, make the suet crust. Mix the flour and salt in a large bowl. Add the suet and stir until it's distributed evenly. Add the cold water a little at a time, stirring with a knife until a soft, slightly sticky dough forms. Knead gently until just combined; don't overwork it."},{"text":"Lightly flour a work surface. Roll out two-thirds of the dough into a circle about 40 cm across and 5 mm thick. It should be large enough to line a 1.5-litre pudding basin with some hanging over the edge."},{"text":"Use this large circle to line the pudding basin, leaving the excess hanging over the rim."},{"text":"Strain the cooled filling, reserving the liquid. Discard the bay leaves and thyme. Spoon the beef and onions into the lined basin, then pour in enough of the reserved liquid to come halfway up the filling (about 200 ml). Save the rest for serving."},{"text":"Roll out the remaining dough into a circle about 25 cm across, 5 mm thick. Lay this on top of the filling. Fold the overhanging pastry inward over the lid, pressing down to seal."},{"text":"Cover the pudding with a pleated piece of baking paper (the pleat allows for expansion), then a pleated piece of foil. Tie both down with string under the lip of the basin."},{"text":"Place the pudding basin in a large pot and add enough boiling water to come halfway up the sides of the basin. Cover the pot with a lid. Steam for 3 hours, checking every 45 minutes and topping up the water if needed, it should stay at the same level."},{"text":"Carefully remove the pudding from the pot. Let it rest for 10 minutes. Warm the reserved liquid in a small pan."},{"text":"Turn the pudding out onto a warm plate or serving bowl. Serve with the warmed gravy poured over the top, and mashed potato on the side."}],"id":"9309bc2a-9f30-4f85-9cfc-d2554c594a88"},{"notes":["Make the dough the day before if it suits you, cold dough ferments gently overnight. Shape and prove the next morning.","If you grind whole cardamom pods yourself, use about 1½ tsp of pods; they're more fragrant than pre-ground.","Semlor are best eaten the day they're made. Store in an airtight container for up to a day, but the bun will soften.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"5271f5da-2631-497e-9617-ad94681684c1"},{"notes":["If you can't find khoya, reduce 500 ml milk slowly in a heavy pan until it becomes a thick paste (about 30 minutes), then use that instead, it will give you more authentic flavour and texture.","For a softer sandesh (Arnab's preference), use only 50 g khoya and don't chill for as long; for a firmer set (his wife's way), add an extra 25 g khoya.","Regional variations: try adding a few strands of saffron, a tablespoon of mango pulp, or a teaspoon of rose water instead of cardamom, the arguments are endless and that's rather the point."],"steps":[{"text":"Bring the milk to a rolling boil in a heavy-bottomed pan over high heat, until it foams up and rises towards the rim. Once it reaches a full boil, remove from the heat."},{"text":"Add the yoghurt slowly, stirring gently. The milk will curdle immediately. Let it sit for 2 minutes, then pour through a fine sieve lined with muslin cloth, collecting the whey in a bowl beneath. Let it drain for 5 minutes."},{"text":"Gather the corners of the muslin and hang it to drain for 30 minutes until the paneer is quite dry but still soft."},{"text":"Turn the paneer into a bowl and crumble it finely with your fingertips. Add the khoya, sugar, cardamom seeds (discarding the husks), and salt. Mix gently but thoroughly until the mixture just holds together."},{"text":"Divide the mixture into 12 portions and shape each into a small smooth ball or oval with damp hands. You can press each into a small mould if you have one, then tap it out onto a plate."},{"text":"Chill for at least 15 minutes before serving. Store in an airtight container in the fridge for up to 3 days."}],"id":"08f16912-d659-445a-864b-6b291d535ad3"},{"notes":["Sole is the classic choice, but halibut, plaice or any firm white fish works. You can also cook fillets, they'll need only 1–2 minutes per side.","The brown butter is everything. Don't skip it or rush it; the aroma tells you when it's ready."],"steps":[{"text":"Pat the sole dry with paper towels. Season inside and out with salt and pepper."},{"text":"Spread the flour on a shallow plate. Lightly coat both sides of each fish, shaking off the excess."},{"text":"Heat the oil in a large frying pan over medium-high heat until shimmering."},{"text":"Lay the sole in the pan and cook, without moving, for 2–3 minutes until the skin is golden and crisp. Flip and cook the other side for 2–3 minutes until cooked through."},{"text":"Transfer the fish to a warm plate. Reduce the heat to medium, add the butter to the same pan, and let it melt and brown, swirling gently, for 1–2 minutes until it smells nutty and turns golden."},{"text":"Pour the brown butter over the fish, squeeze lemon juice over the top (it will sizzle briefly), scatter with parsley if using, and serve at once while the butter is still hot and nutty."}],"id":"20bc01fb-f1da-4793-9da1-9c93d20fd7b4"},{"notes":["For extra richness, some cooks stir in a spoonful of crème fraîche or Greek yoghurt just before serving.","Make this ahead and reheat gently, the flavour deepens overnight."],"id":"11ee35b8-7029-4f2c-9c05-30fe579fb588"},{"notes":["Kalua pork keeps well in the fridge for 4 days, and freezes for up to 3 months. Reheat gently with a splash of water.","Serve with rice, cabbage slaw and gravy for a real plate lunch, or use it for musubi.","The longer you cook it, the more tender it gets, even 8 or 9 hours won't hurt.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"id":"ee778302-0727-480f-a85c-34ea49898277"},{"notes":["Make the gochujang butter ahead and keep it in a pot in the fridge; it'll come together faster in the morning.","Use leftover rice from the night before, or make a quick batch while you wait for the egg to fry.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"932fe6b4-6b1a-44b4-a5c6-5bd6c18b1928"},{"notes":["This pudding can be made a few hours ahead and gently reheated, or served at room temperature.","Use good-quality rose water, it should smell fragrant but not perfumy. Add it slowly and taste as you go."],"steps":[{"text":"Bring the water to a boil in a large saucepan. Add the sago slowly, stirring constantly to prevent lumps from forming. Cook, stirring often, until the sago is translucent and tender, about 12 minutes."},{"text":"Add the milk, caster sugar, cinnamon stick and crushed cardamom pods. Stir well and bring to a gentle simmer until the sugar has dissolved and the milk is fragrant."},{"text":"Cook, stirring occasionally, until the pudding thickens slightly and the sago pearls are completely soft, about 5 minutes. The mixture should be creamy but not stiff."},{"text":"Remove from the heat and stir through the rose water. Taste and add a pinch of salt to balance the sweetness. Discard the cinnamon stick."},{"text":"Divide among bowls while still warm and dust lightly with ground cinnamon. Serve warm or at room temperature."}],"id":"dd9cd41f-cc82-47b7-8176-19e73288bcb4"},{"notes":["Make the sofregit ahead: cook the onions and tomatoes up to an hour before, then reheat gently before adding the rice.","Fresh squid ink from the fishmonger can replace the sachets, ask for 2 sachets' worth (about 4 g). It will be fresher and give a rounder flavour.","Arròs negre reheats poorly, so cook it fresh and serve at once, still warm from the pan.","Food safety: Cook mussels, clams and pipis only if they are alive and tightly closed (or close when tapped), and discard any that stay shut after cooking."],"steps":[{"text":"In your rice pan or large shallow casserole over medium heat, warm the olive oil. Add the chopped onions and cook very slowly, stirring often, until completely soft and lightly golden, this is the sofregit, and it should take 12 to 15 minutes. Do not rush it; this is where the flavour lives."},{"text":"Add the tinned tomatoes to the sofregit and stir well. Cook for another 5 to 8 minutes, until the sauce thickens slightly and the raw tomato taste disappears. Season with salt and pepper."},{"text":"Stir in the garlic and chilli (if using), and cook for 1 minute until fragrant."},{"text":"Add the rice and stir constantly for 2 minutes, coating each grain with the sofregit and oil."},{"text":"Dissolve the squid ink sachets in the warm stock until the stock is jet black, then pour the stock gradually into the rice, stirring occasionally. Bring to a simmer until bubbles break across the surface."},{"text":"Cook the rice uncovered at a gentle simmer for about 15 to 18 minutes, stirring occasionally, until the rice is almost tender and the liquid has been mostly absorbed."},{"text":"Scatter the squid rings and mussels across the top of the rice. Do not stir them in. Continue cooking for 5 to 7 minutes, until the squid is just cooked through, the mussel shells have opened (discard any that don't), and the rice is tender with a slight bite. The bottom should form a thin, crispy layer (called socarrat)."},{"text":"Remove from heat, cover loosely with foil, and rest for 3 minutes. Scatter fresh parsley over the top and serve at the table in the pan."}],"id":"c16b7f17-3e03-4212-8896-9e84a51f05ae"},{"notes":["Make it a day ahead and reheat gently, the flavours deepen overnight.","If you can't find fresh palm nuts, use tinned palm cream (about 800 ml), though fresh is far superior. Skip the pounding and straining; just heat the tinned cream gently and follow from step 3.","Stockfish is essential, dried, smoked whole fish. Don't substitute with stock cubes or powder, you'll lose the soul of the soup.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Pound the palm nuts in a large bowl with 2 litres of hot water (not boiling), working in batches. Press through a fine sieve or colander lined with muslin cloth, squeezing gently to extract all the cream. Reserve this golden liquid and discard the fibre."},{"text":"In a large pot, bring 1 litre of water to the boil. Add the stockfish, one halved onion, and a pinch of salt. Simmer for 20 minutes, then remove the stockfish and set aside to cool. Strain the cooking liquid and reserve it (discard the onion)."},{"text":"Once the stockfish is cool enough to handle, remove the meat from the bones and break into chunks. Discard the bones."},{"text":"Pour the palm nut cream into the pot over medium heat. Stir constantly for 3–4 minutes until it thickens slightly and the oil begins to separate on top, this is how you know it's ready."},{"text":"Add the reserved stockfish cooking liquid, the stockfish meat, dried crayfish, remaining halved onion, and the scotch bonnet chillies if using. Stir well and simmer gently for 20 minutes, stirring occasionally to prevent sticking."},{"text":"Stir in the ground crayfish, salt, and black pepper. Taste and adjust seasoning. Simmer for another 10 minutes, then remove from heat. Remove the onion halves and whole chillies before serving."},{"text":"Serve hot with boiled white rice, gari, or fufu."}],"id":"5641fd55-6c6e-43a6-8c8a-ba7583956f34"},{"notes":["Make ahead: Cook the rice and prepare the chikuwa mixture up to 4 hours ahead. Reheat gently and pour over fresh rice.","Chikuwa keeps in the fridge for up to a week, so this is perfect for bento prep.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Combine dashi, soy sauce, mirin and sugar in a small saucepan or shallow pan. Bring to a simmer over medium heat until the sugar has dissolved and small bubbles appear at the edges."},{"text":"Add the sliced chikuwa and simmer for 2 minutes until heated through."},{"text":"Lightly beat the eggs in a bowl. Pour into the simmering broth in a thin stream, stirring gently until the egg is just set but still soft, about 1 minute."},{"text":"Divide the cooked rice between two bowls. Spoon the chikuwa, egg and sauce over the top. Garnish with spring onion if using, and serve hot."}],"id":"8d26edbf-621b-4f0c-90e6-fe2b8881dc33"},{"notes":["The batter can be made the night before and stored in the fridge, it actually develops better flavour overnight.","Wonton wrappers crisp up quickly, so fry them just before you start making the crepes.","A non-stick or well-seasoned crepe pan is essential. The pan must be hot enough that the batter sets instantly, or you'll struggle to spread it."],"steps":[{"text":"Mix plain flour and salt in a bowl. Slowly add water, stirring until smooth. Let the batter rest for 10 minutes."},{"text":"While the batter rests, break the wonton wrappers into rough pieces and fry in a small pan with a little oil until crispy and golden, about 2 minutes. Set aside."},{"text":"Heat a large non-stick pan or crepe pan over high heat. It should be very hot, test with a drop of water; it should sizzle and evaporate immediately."},{"text":"Pour 120 ml of batter into the centre of the pan and immediately tilt and rotate the pan so the batter spreads into a thin, even circle about 20 cm across. Work quickly."},{"text":"Let the batter cook for about 30 seconds until the bottom is set and starts to turn light golden. Crack an egg onto one half of the crepe, then use a spatula to break the yolk and spread it evenly."},{"text":"Scatter half the chopped spring onion and half the crispy wonton pieces over the egg. Fold the other half of the crepe over to enclose the filling, pressing gently."},{"text":"Cook for another 30 seconds until the egg is set, then slide onto a plate. Serve immediately with sweet chilli sauce and soy sauce for dipping."},{"text":"Repeat with the remaining batter, egg, spring onion and wonton to make a second jianbing."}],"id":"3b8e4204-f4e6-44fc-b502-605049783dbe"},{"steps":[{"text":"Heat the oil in a large pot over medium heat. Add the onion and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Add the garlic and ginger, and cook for 1 minute until fragrant."},{"text":"Stir in the cumin, coriander and turmeric, and cook for 1 minute to release the spices."},{"text":"Add the eggplant chunks and stir to coat in the spice mixture. Cook for 5 minutes, stirring occasionally."},{"text":"Pour in the coconut milk and bring to a simmer until gentle bubbles appear and the sauce is slightly thickened. Add the chopped chillies and stir well."},{"text":"Reduce heat to low and simmer gently, uncovered, for 20 minutes until the eggplant is very tender. Stir occasionally."},{"text":"Taste and add salt as needed. Serve hot, scattered with fresh coriander if you like."}],"id":"95c327e5-703b-4c9b-8a2d-78ff2b2189ee"},{"notes":["Make the rice cakes up to 2 hours ahead and keep them at room temperature, covered with a damp cloth. Assemble and fold just before serving so they stay pliable.","If you can't find banana leaves, plastic wrap works fine, or serve the bánh nậm on a plate with lettuce underneath instead.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"5ca24c75-c406-4c47-9990-2e57053df80e"},{"notes":["Serve warm or at room temperature with crusty bread for scooping.","Keeps in the fridge for up to 3 days and tastes even better the next day.","The notebook's version with dried tomatoes works too, reduce the roasting time to about 45 minutes if using them."],"id":"70898d41-065c-41b4-b33d-d51c5d11e9e4"},{"notes":["Halloumi must be proper Cyprus halloumi, soft halloumi will melt and won't squeak. Find it at the deli counter or with the international cheeses.","Eat it straight from the pan while it's still hot and squeaky. Once it cools, it toughens up.","This works as an appetiser before a big feed, or as a quick snack with cold beer on a Saturday arvo."],"steps":[{"text":"Heat a shallow pan over medium-high heat. Pour in enough oil so it's about 5 mm deep, then get it really hot, it should shimmer and just start to smoke."},{"text":"Dust the halloumi slices lightly in flour on both sides, shaking off any excess."},{"text":"When the oil's smoking, carefully lay the halloumi slices into the pan. You should hear them sizzle immediately. Don't move them."},{"text":"Cook for about 2 minutes until the underside is deep golden. Flip and cook the other side for another 2 minutes until it's the same colour. It should squeak when you bite into it."},{"text":"Transfer to a plate, season with salt, and serve straight away with lemon wedges on the side. Squeeze lemon over each piece and eat it hot."}],"id":"33f8f5b5-a4cf-4d86-af56-345acdcfa396"},{"notes":["Make ahead: Shape the kebabs up to 4 hours ahead, cover and refrigerate until ready to fry.","For extra flavour, add 1 tbsp of tamarind paste to the mixture before shaping.","These freeze well raw: freeze shaped kebabs on a tray, then transfer to a container. Fry from frozen, allowing an extra 2 to 3 minutes per side.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"49d73230-5dea-4ca7-a6d9-046ca6e2fe9e"},{"notes":["The oysters must be eaten as soon as they come out of the oven, while the butter is still foaming.","If shucking oysters yourself, chill them in the freezer for 15 minutes first, they open more easily.","You can make the herb butter a few hours ahead and chill it, then scoop it on to the oysters just before baking."],"id":"bb4730fc-0ea4-4d10-9993-e32ba4b2dcae"},{"notes":["Press the tofu overnight or for at least 2 hours before cooking so it fries crispy and stays that way. You can make the filling components ahead and assemble the rolls right before serving.","Swap the herbs for whatever's fresh, Thai basil works beautifully, or try rocket for something peppery."],"id":"5bac0e7a-09ef-49cc-bcde-00c19249e522"},{"notes":["Don't overcrowd the pan, if you're cooking for more than 4, cook in two batches so the squid fries rather than steams.","Squid cooks fast: longer than 3–4 minutes and it toughens. In and out.","Serve with crusty bread to mop up the pan juices.","Food safety: Cook squid and octopus until opaque and firm, and keep seafood chilled until you cook it."],"steps":[{"text":"Score the squid tubes in a fine crosshatch, cutting about halfway through the flesh. Pat dry with paper towel and cut into bite-sized pieces (about 4 cm square)."},{"text":"Place a large frying pan or wok over high heat until it's smoking hot, about 2 minutes."},{"text":"Add the olive oil, then immediately add the squid pieces, chilli and garlic. Stir constantly for about 2 minutes, the squid will curl and become opaque."},{"text":"Season with salt and pepper to taste, then squeeze lemon juice over and toss through."},{"text":"Serve immediately, scattered with fresh parsley if you like, with extra lemon wedges on the side."}],"id":"74052578-daeb-4943-99c2-414945f3af42"},{"diets":[],"notes":["Make the pasta and filling up to 2 hours ahead; keep the cut agnolotti on a tray in the fridge, uncovered, until you cook them.","If your filling is too wet, the agnolotti will split. If the ricotta is very creamy, drain it in a sieve lined with kitchen paper for 10 minutes first.","For a vegetarian version, use a vegetarian hard cheese (made without animal rennet)."],"steps":[{"text":"Make the pasta dough: tip flour into a mound on a work surface, make a well in the centre, crack in eggs, add oil and a pinch of salt. Work with a fork until shaggy, then knead for 8 minutes until smooth. Wrap and rest 20 minutes."},{"text":"While the dough rests, make the filling: mix ricotta, spinach, parmesan, egg yolk and garlic. Season generously with salt, pepper and nutmeg, taste it, it should be well-seasoned."},{"text":"Dust your work surface. Roll the dough to the thickness of a coin (about 1 mm). Using a 7 cm round cutter, stamp out circles."},{"text":"Place a small spoonful of filling (about ½ tsp) on one half of each circle. Fold in half, press the edges to seal, then fold the corners up and press them together to make a purse shape. Place on a floured tray as you go."},{"text":"Bring a large pot of salted water to a boil. Melt the butter in a separate pan over medium heat until it turns golden and smells nutty, 5 minutes. Add the sage leaves."},{"text":"Drop the agnolotti into the boiling water. They'll sink, then bob to the surface after 2–3 minutes. Cook for another 2 minutes, then remove with a slotted spoon and add to the brown butter. Toss gently."},{"text":"Divide among bowls. Add a pinch of salt and grate parmesan over the top."}],"id":"97270ac2-cdc8-4191-b895-dd7b9fd843c4"},{"notes":["Use fresh egg noodles from the fridge section if you can, they won't clump. No fresh? Cooked noodles work fine; just break them up as you add them.","The paste can be made 30 minutes ahead and kept in a bowl.","Push for medium heat, you want the paste to fry properly but the noodles not to burn on the bottom.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"8ef2ad89-ef4c-4d1f-b409-bdb5719cc1df"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;